package com.keevo.inventory.api;

import java.util.Map;
import java.util.UUID;

/**
 * Validation of an inventory session, which rewrites stock with the counted quantities
 * (Story 12.2b).
 *
 * @param movementIds ADJUSTMENT movement ids generated by an offline device, keyed
 *                    {@code "productId|variantId"} (empty variant when none); empty online
 */
public record ValidateCountingInput(UUID sessionId, UUID actorId, Map<String, UUID> movementIds) {

    public ValidateCountingInput {
        movementIds = movementIds != null ? Map.copyOf(movementIds) : Map.of();
    }
}
